 "content": "def transform(grid):
    """Stamp a 3x3 color-1 patch around embedded color-2 markers."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            adjacent_threes = sum(
                0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 3
                for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1))
            )
            if adjacent_threes >= 2:
                centers.append((r, c))
    for r, c in centers:
        for nr in range(max(0, r-1), min(h, r+2)):
            for nc in range(max(0, c-1), min(w, c+2)):
                if grid[nr][nc] != 2:
                    out[nr][nc] = 1
    return out
